class WorkforcePayTemplatePublicationPostgresTest extends WorkforcePostgresTest {
 TemplatePublicationService publications;TemplateAdoptionService adoptions;PayrollConfigurationRepository configs;PayrollConfigurationService payroll;WorkforceAudit audit;
 @BeforeEach void publicationSetup(){var mapper=new ObjectMapper().findAndRegisterModules();var json=new WorkforceJson(mapper);audit=new WorkforceAudit(logs,mapper);configs=new PayrollConfigurationRepository(jdbc,json);var r=new TemplatePublicationRepository(jdbc,json,clock);publications=proxy(new TemplatePublicationService(access,r,configs,audit));adoptions=proxy(new TemplateAdoptionService(access,r,configs,audit));payroll=proxy(new PayrollConfigurationService(access,new PayrollAccess(access,directory,jdbc),configs,repository,audit,clock));}
 SalaryTemplate installedTemplate(String name,Rule rule){var t=new SalaryTemplate(UUID.randomUUID(),company,name,PayrollRules.normalize(rule),true,1);var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());jdbc.update("insert into workforce_pay_templates(id,tenant_id,company_id,name,snapshot,enabled,version) values(?,?,?,?,?::jsonb,true,1)",t.id(),tenant,company,name,json.write(t));jdbc.update("insert into workforce_pay_effective_evidence(id,tenant_id,company_id,kind,subject_kind,subject_id,version,result) values(?,?,?,'legacy-valid','template',?,1,?::jsonb)",UUID.randomUUID(),tenant,company,t.id(),json.write(t));return t;}
 Rule rule(String rate){return new Rule("monthly",rate,"8","44",false,"1.5",List.of());}
 Draft draft(boolean future){return publications.save(admin,store,UUID.randomUUID(),new DraftWrite(0L,"Tenant Standard",rule("3000"),List.of(company),List.of(store),future));}
 Release release(Draft d){return publications.publish(admin,store,d.id(),new Publish(UUID.randomUUID(),d.version()));}
 Adoption enable(Release r,UUID shop,long expected){return adoptions.enable(admin,shop,r.masterId(),new Enable(UUID.randomUUID(),r.version(),expected));}
 @Test void publishedSnapshotIsFixedAndUpgradeDoesNotOverwriteAdoption(){var d=draft(false);var r=release(d);var a=enable(r,store,0);publications.save(admin,store,d.id(),new DraftWrite(1L,d.name(),rule("4000"),d.companyIds(),d.storeIds(),false));var r2=publications.publish(admin,store,d.id(),new Publish(UUID.randomUUID(),2L));assertThat(adoptions.preview(admin,store,d.id(),1).release()).isEqualTo(r);assertThat(adoptions.library(admin,store).getFirst().state()).isEqualTo("updateAvailable");assertThat(configs.findTemplate(tenant,a.materializedTemplateId()).orElseThrow().rule().rate()).isEqualTo("3000.00");var b=enable(r2,store,1);assertThat(b.storeVersion()).isEqualTo(2);assertThat(b.materializedTemplateId()).isNotEqualTo(a.materializedTemplateId());}
 @Test void visibleDoesNotEnableAndRepeatDoesNotCopy(){var r=release(draft(false));assertThat(adoptions.library(admin,store).getFirst().adoption()).isNull();assertThat(payroll.listTemplates(admin,store,company)).isEmpty();var command=new Enable(UUID.randomUUID(),1L,0L);var a=adoptions.enable(admin,store,r.masterId(),command);assertThat(adoptions.enable(admin,store,r.masterId(),command)).isEqualTo(a);assertThat(enable(r,store,1)).isEqualTo(a);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_template_adoptions where tenant_id=?",Integer.class,tenant)).isEqualTo(1);assertThatThrownBy(()->adoptions.enable(admin,store,r.masterId(),new Enable(command.commandId(),1L,1L))).isInstanceOf(WorkforceException.class).hasMessage("WORKFORCE_CONFLICT");}
 @Test void futureScopeUsesCreatedAtAndInactiveExistingSet(){jdbc.update("update stores set status='inactive' where id=?",sibling);var r=release(draft(true));jdbc.update("update stores set status='active' where id=?",sibling);assertThat(adoptions.library(admin,sibling)).isEmpty();UUID fresh=UUID.randomUUID();jdbc.update("insert into stores(id,tenant_id,operating_entity_id,store_code,display_name,status,timezone,locale,date_format,time_format,currency) values(?,?,?,?,'Future','active','Asia/Singapore','zh-CN','DD-MM-YYYY','HH:mm','SGD')",fresh,tenant,company,"s-"+fresh);var expanded=new HashSet<>(admin.storeIds());expanded.add(fresh);var futureActor=new CurrentActor(tenant,adminId,"staff",admin.roles(),admin.permissions(),expanded);assertThat(adoptions.library(futureActor,fresh).getFirst().state()).isEqualTo("available");assertThat(adoptions.library(futureActor,fresh).getFirst().adoption()).isNull();assertThatThrownBy(()->adoptions.library(admin,fresh)).isInstanceOf(WorkforceException.class);jdbc.update("update stores set operating_entity_id=? where id=?",otherCompany,fresh);assertThat(adoptions.library(futureActor,fresh)).isEmpty();}
 @Test void selectedStoresHaveIndependentMaterializedIdsAndLegacyRemainsShared(){var d=publications.save(admin,store,UUID.randomUUID(),new DraftWrite(0L,"Both",rule("2000"),List.of(company),List.of(store,sibling),false));var r=release(d);var a=enable(r,store,0);var b=enable(r,sibling,0);assertThat(a.materializedTemplateId()).isNotEqualTo(b.materializedTemplateId());var legacy=installedTemplate("Legacy",rule("10"));assertThat(payroll.listTemplates(admin,store,company)).extracting(SalaryTemplate::id).containsExactlyInAnyOrder(a.materializedTemplateId(),legacy.id());assertThat(payroll.listTemplates(admin,sibling,company)).extracting(SalaryTemplate::id).containsExactlyInAnyOrder(b.materializedTemplateId(),legacy.id());assertThatThrownBy(()->payroll.saveTemplate(admin,sibling,a.materializedTemplateId(),new TemplateWrite(1L,company,"Hacked",rule("1"),true))).isInstanceOf(WorkforceException.class).hasMessage("WORKFORCE_MANAGED_TEMPLATE_IMMUTABLE");}
 @Test void storeManagementDoesNotGrantPersonalSalaryAccess(){var r=release(draft(false));var managerId=account("store_manager",Set.of(store),Set.of("workforce.view"));admins.save(admin,store,managerId,new WorkforceDtos.AdministratorWrite(0L,true,null));var manager=new CurrentActor(tenant,managerId,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));assertThat(adoptions.library(manager,store)).hasSize(1);assertThat(adoptions.enable(manager,store,r.masterId(),new Enable(UUID.randomUUID(),1L,0L))).isNotNull();assertThatThrownBy(()->payroll.listTemplates(manager,store,company)).isInstanceOf(WorkforceException.class);assertThatThrownBy(()->publications.save(manager,store,UUID.randomUUID(),new DraftWrite(0L,"X",rule("1"),List.of(company),List.of(store),false))).isInstanceOf(WorkforceException.class);}
 @Test void authorizationIsRecheckedOnReplayAndScopeChanges(){var r=release(draft(false));var c=new Enable(UUID.randomUUID(),1L,0L);adoptions.enable(admin,store,r.masterId(),c);jdbc.update("update stores set status='inactive' where id=?",store);assertThatThrownBy(()->adoptions.enable(admin,store,r.masterId(),c)).isInstanceOf(WorkforceException.class);jdbc.update("update stores set status='active',operating_entity_id=? where id=?",otherCompany,store);assertThatThrownBy(()->adoptions.enable(admin,store,r.masterId(),c)).isInstanceOf(WorkforceException.class);}
 @Test void foreignMissingAndAppGateDeniedAreRejected(){var r=release(draft(false));assertThatThrownBy(()->adoptions.preview(admin,sibling,r.masterId(),1)).isInstanceOf(WorkforceException.class);assertThatThrownBy(()->adoptions.preview(admin,store,UUID.randomUUID(),1)).isInstanceOf(WorkforceException.class);var platform=new CurrentActor(tenant,adminId,"staff",Set.of("platform_admin","tenant_admin"),admin.permissions(),admin.storeIds());assertThatThrownBy(()->adoptions.library(platform,store)).isInstanceOf(WorkforceException.class);var mixed=new CurrentActor(tenant,adminId,"staff",Set.of("tenant_admin","store_manager"),admin.permissions(),admin.storeIds());assertThatThrownBy(()->publications.drafts(mixed,store)).isInstanceOf(WorkforceException.class);doAnswer(c->{var q=(com.rpb.reservation.appgate.application.AppGateAccessRequest)c.getArgument(0);return com.rpb.reservation.appgate.domain.AppGateDecision.deny(q.appKey(),q.tenantId(),q.storeId(),q.requiredPermission(),com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_EXPIRED);}).when(gate).evaluate(any());assertThatThrownBy(()->adoptions.library(admin,store)).isInstanceOf(WorkforceException.class).hasMessage("STORE_APP_EXPIRED");}
 @Test void scopeAndRuleValidationAndAuditRollback(){assertThatThrownBy(()->publications.save(admin,store,UUID.randomUUID(),new DraftWrite(0L,"X",rule("1e3"),List.of(company),List.of(store),false))).isInstanceOf(WorkforceException.class);assertThatThrownBy(()->publications.save(admin,store,UUID.randomUUID(),new DraftWrite(0L,"X",rule("1"),List.of(otherCompany),List.of(store),false))).isInstanceOf(WorkforceException.class);var d=draft(false);when(logs.append(any(com.rpb.reservation.common.scope.StoreScope.class),any())).thenThrow(new IllegalStateException("audit"));assertThatThrownBy(()->release(d)).isInstanceOf(IllegalStateException.class);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_template_releases where tenant_id=?",Integer.class,tenant)).isZero();}
 @Test void databaseEnforcesReleaseAndAdoptionImmutability(){var r=release(draft(false));var a=enable(r,store,0);assertThatThrownBy(()->jdbc.update("update workforce_pay_template_releases set snapshot='{}'::jsonb where tenant_id=?",tenant)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->jdbc.update("delete from workforce_pay_template_adoptions where id=?",a.id())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->jdbc.update("update workforce_pay_templates set name='hack' where id=?",a.materializedTemplateId())).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void managedIdsCannotCrossStoresThroughProfileAndPositionMapping(){
  UUID employee=UUID.randomUUID();employees.save(admin,store,employee,command(0,List.of(store,sibling),company,null,null));var e=repository.find(tenant,employee).orElseThrow();var r=release(draft(false));var a=enable(r,store,0);var t=configs.findTemplate(tenant,a.materializedTemplateId()).orElseThrow();
  var cpf=new com.rpb.reservation.workforce.statutory.StatutoryDtos.CpfProfile("citizen",LocalDate.of(1990,1,1),null,"GG","");UUID profileId=UUID.randomUUID();var c=new ProfileWrite(0L,company,employee,LocalDate.of(2026,10,1),t.id(),t.rule(),cpf,null,new CdacProfile("not_applicable","Explicit standard declaration"));
  var p=payroll.saveProfile(admin,store,profileId,c);assertThatThrownBy(()->payroll.saveProfile(admin,sibling,profileId,c)).isInstanceOf(WorkforceException.class).hasMessage("WORKFORCE_FORBIDDEN");assertThatThrownBy(()->payroll.saveProfile(admin,sibling,UUID.randomUUID(),c)).isInstanceOf(WorkforceException.class);
  var defaults=proxy(new PositionSalaryDefaultsService(access,new PayrollAccess(access,directory,jdbc),configs,repository,new com.rpb.reservation.workforce.positions.PositionRepository(jdbc),audit));var mapping=defaults.save(admin,store,UUID.randomUUID(),new DefaultWrite(0L,company,e.positionId(),LocalDate.of(2026,10,1),t.id(),true));
  assertThat(defaults.preview(admin,store,company,employee,LocalDate.of(2026,10,1),null).template().id()).isEqualTo(t.id());assertThatThrownBy(()->defaults.preview(admin,sibling,company,employee,LocalDate.of(2026,10,1),null)).isInstanceOf(WorkforceException.class);assertThatThrownBy(()->defaults.preview(admin,sibling,company,employee,LocalDate.of(2026,10,1),t.id())).isInstanceOf(WorkforceException.class);assertThatThrownBy(()->defaults.save(admin,sibling,mapping.id(),new DefaultWrite(0L,company,e.positionId(),mapping.effectiveFrom(),t.id(),true))).isInstanceOf(WorkforceException.class);
  var d=publications.drafts(admin,store).getFirst();publications.save(admin,store,d.id(),new DraftWrite(1L,d.name(),rule("4000"),d.companyIds(),d.storeIds(),false));var upgrade=publications.publish(admin,store,d.id(),new Publish(UUID.randomUUID(),2L));enable(upgrade,store,1);
  assertThat(payroll.saveProfile(admin,store,profileId,c)).isEqualTo(p);assertThatThrownBy(()->payroll.saveProfile(admin,store,UUID.randomUUID(),c)).isInstanceOf(WorkforceException.class);assertThat(configs.templateAccessible(tenant,store,t.id(),true)).isTrue();assertThat(configs.templateAccessible(tenant,sibling,t.id(),true)).isFalse();
 }
 @Test void publicationAndEnableConcurrencyDoNotDuplicateSnapshots()throws Exception{
  var d=draft(false);UUID command=UUID.randomUUID();var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var first=pool.submit(()->publications.publish(admin,store,d.id(),new Publish(command,1L)));var second=pool.submit(()->publications.publish(admin,store,d.id(),new Publish(command,1L)));var r=first.get(20,java.util.concurrent.TimeUnit.SECONDS);assertThat(second.get(20,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(r);
  var c=new Enable(UUID.randomUUID(),1L,0L);var a=pool.submit(()->adoptions.enable(admin,store,d.id(),c));var b=pool.submit(()->adoptions.enable(admin,store,d.id(),c));assertThat(a.get(20,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(b.get(20,java.util.concurrent.TimeUnit.SECONDS));assertThat(jdbc.queryForObject("select count(*) from workforce_pay_template_adoptions where tenant_id=?",Integer.class,tenant)).isEqualTo(1);
  }finally{pool.shutdownNow();}
 }
 @Test void lateCommittedNewStoreIsNotLostByTransactionStartTimestamp(){var r=release(draft(true));UUID fresh=UUID.randomUUID();jdbc.update("insert into stores(id,tenant_id,operating_entity_id,store_code,display_name,status,timezone,locale,date_format,time_format,currency,created_at) values(?,?,?,?,'Late commit','active','Asia/Singapore','zh-CN','DD-MM-YYYY','HH:mm','SGD',?::timestamptz)",fresh,tenant,company,"s-"+fresh,r.publishedAt().minusSeconds(60).toString());var shops=new HashSet<>(admin.storeIds());shops.add(fresh);var actor=new CurrentActor(tenant,adminId,"staff",admin.roles(),admin.permissions(),shops);assertThat(adoptions.library(actor,fresh)).hasSize(1);}
 @Test void storeCompanyChangeDoesNotReuseOldCompanyMaterialization(){var d=publications.save(admin,store,UUID.randomUUID(),new DraftWrite(0L,"Two companies",rule("3000"),List.of(company,otherCompany),List.of(store,otherStore),false));var r=release(d);var command=new Enable(UUID.randomUUID(),1L,0L);var a=adoptions.enable(admin,store,d.id(),command);jdbc.update("update stores set operating_entity_id=? where id=?",otherCompany,store);assertThatThrownBy(()->adoptions.enable(admin,store,d.id(),command)).isInstanceOf(WorkforceException.class).hasMessage("WORKFORCE_FORBIDDEN");assertThat(adoptions.preview(admin,store,d.id(),1).adoption()).isNull();var b=enable(r,store,0);assertThat(b.companyId()).isEqualTo(otherCompany);assertThat(b.storeVersion()).isEqualTo(2);assertThat(b.materializedTemplateId()).isNotEqualTo(a.materializedTemplateId());assertThat(configs.templateAccessible(tenant,store,a.materializedTemplateId(),false)).isFalse();}
 @Test void tenantAndHeadOfficeDraftScopeCannotBeBroadenedByCurrentStoreAccess(){var d=draft(false);var limited=new CurrentActor(tenant,adminId,"staff",admin.roles(),admin.permissions(),Set.of(store));assertThat(publications.drafts(limited,store)).isEmpty();assertThatThrownBy(()->publications.publish(limited,store,d.id(),new Publish(UUID.randomUUID(),1L))).isInstanceOf(WorkforceException.class);UUID foreign=UUID.randomUUID(),shop=UUID.randomUUID();jdbc.update("insert into tenants(id,tenant_code,display_name,status) values(?,?,'Foreign','active')",foreign,"f-"+foreign);jdbc.update("insert into stores(id,tenant_id,store_code,display_name,status,timezone,locale,date_format,time_format,currency) values(?,?,?,'Foreign','active','Asia/Singapore','zh-CN','DD-MM-YYYY','HH:mm','SGD')",shop,foreign,"f-"+shop);var forged=new CurrentActor(foreign,adminId,"staff",admin.roles(),admin.permissions(),Set.of(shop));assertThatThrownBy(()->adoptions.preview(forged,shop,d.id(),1)).isInstanceOf(WorkforceException.class);}
 @Test void futureCompanyMayPublishBeforeItsFirstStoreExists(){UUID futureCompany=UUID.randomUUID();jdbc.update("insert into operating_entities(id,tenant_id,entity_code,display_name,status) values(?,?,?,'Future company','active')",futureCompany,tenant,"c-"+futureCompany);var d=publications.save(admin,store,UUID.randomUUID(),new DraftWrite(0L,"Future company",rule("2000"),List.of(futureCompany),List.of(),true));assertThat(release(d).companyIds()).containsExactly(futureCompany);assertThat(adoptions.library(admin,store)).isEmpty();}
 @Test void allAppGateDenialsAndNonManagerAreRejected(){release(draft(false));UUID staffId=account("store_staff",Set.of(store),Set.of("workforce.view"));var staff=new CurrentActor(tenant,staffId,"staff",Set.of("store_staff"),Set.of("workforce.view"),Set.of(store));assertThatThrownBy(()->adoptions.library(staff,store)).isInstanceOf(WorkforceException.class);for(var reason:com.rpb.reservation.appgate.domain.AppGateDenyReason.values()){doAnswer(c->{var q=(com.rpb.reservation.appgate.application.AppGateAccessRequest)c.getArgument(0);return com.rpb.reservation.appgate.domain.AppGateDecision.deny(q.appKey(),q.tenantId(),q.storeId(),q.requiredPermission(),reason);}).when(gate).evaluate(any());assertThatThrownBy(()->adoptions.library(admin,store)).isInstanceOf(WorkforceException.class).hasMessage(reason.name());}}
 @Test void auditFailureRollsBackMaterializationAdoptionAndCommand(){var r=release(draft(false));var c=new Enable(UUID.randomUUID(),1L,0L);when(logs.append(any(com.rpb.reservation.common.scope.StoreScope.class),any())).thenThrow(new IllegalStateException("audit"));assertThatThrownBy(()->adoptions.enable(admin,store,r.masterId(),c)).isInstanceOf(IllegalStateException.class);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_template_adoptions where tenant_id=?",Integer.class,tenant)).isZero();assertThat(jdbc.queryForObject("select count(*) from workforce_pay_templates where tenant_id=?",Integer.class,tenant)).isZero();assertThat(jdbc.queryForObject("select count(*) from workforce_pay_template_commands where id=?",Integer.class,c.commandId())).isZero();}
 @Test void commandIdentityBindsActorAndAction(){var d=draft(false);UUID command=UUID.randomUUID();var r=publications.publish(admin,store,d.id(),new Publish(command,1L));assertThatThrownBy(()->adoptions.enable(admin,store,d.id(),new Enable(command,1L,0L))).isInstanceOf(WorkforceException.class).hasMessage("WORKFORCE_CONFLICT");var c=new Enable(UUID.randomUUID(),1L,0L);adoptions.enable(admin,store,d.id(),c);UUID managerId=account("store_manager",Set.of(store),Set.of("workforce.view"));admins.save(admin,store,managerId,new WorkforceDtos.AdministratorWrite(0L,true,null));var manager=new CurrentActor(tenant,managerId,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));assertThatThrownBy(()->adoptions.enable(manager,store,d.id(),c)).isInstanceOf(WorkforceException.class).hasMessage("WORKFORCE_CONFLICT");}
 @Test void invisibleMasterCannotBeTakenOverByNarrowingNewScope(){var d=draft(false);var limited=new CurrentActor(tenant,adminId,"staff",admin.roles(),admin.permissions(),Set.of(otherStore));String before=jdbc.queryForObject("select snapshot::text from workforce_pay_template_masters where id=?",String.class,d.id());assertThatThrownBy(()->publications.save(limited,otherStore,d.id(),new DraftWrite(1L,"Taken over",rule("1"),List.of(otherCompany),List.of(otherStore),false))).isInstanceOf(WorkforceException.class).hasMessage("WORKFORCE_FORBIDDEN");assertThat(jdbc.queryForObject("select snapshot::text from workforce_pay_template_masters where id=?",String.class,d.id())).isEqualTo(before);assertThat(jdbc.queryForObject("select version from workforce_pay_template_masters where id=?",Long.class,d.id())).isEqualTo(1);}
 @Test void authorizedOwnerCanRepairInactiveOrMovedOldDraftScope(){var d=draft(false);jdbc.update("update stores set status='inactive',operating_entity_id=? where id=?",otherCompany,store);var refreshed=new CurrentActor(tenant,adminId,"staff",admin.roles(),admin.permissions(),Set.of(sibling,otherStore));assertThat(publications.drafts(refreshed,sibling)).extracting(Draft::id).contains(d.id());var repaired=publications.save(refreshed,sibling,d.id(),new DraftWrite(1L,d.name(),d.rule(),List.of(company),List.of(sibling),false));assertThat(repaired.version()).isEqualTo(2);assertThat(repaired.storeIds()).containsExactly(sibling);}
 @Test void publicationDirectoryIncludesEmptyCompaniesWithoutGrantingPayrollAccess(){UUID empty=UUID.randomUUID();jdbc.update("insert into operating_entities(id,tenant_id,entity_code,display_name,status) values(?,?,?,'Empty company','active')",empty,tenant,"c-"+empty);assertThat(publications.directory(admin,store).companies()).extracting(WorkforceDtos.Option::id).contains(empty);assertThat(payroll.home(admin,store).companies()).extracting(WorkforceDtos.Option::id).doesNotContain(empty);var limited=new CurrentActor(tenant,adminId,"staff",admin.roles(),admin.permissions(),Set.of(otherStore));assertThat(publications.directory(limited,otherStore).companies()).extracting(WorkforceDtos.Option::id).contains(empty,otherCompany).doesNotContain(company);UUID id=account("store_manager",Set.of(store),Set.of("workforce.view"));admins.save(admin,store,id,new WorkforceDtos.AdministratorWrite(0L,true,null));var manager=new CurrentActor(tenant,id,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));assertThatThrownBy(()->publications.directory(manager,store)).isInstanceOf(WorkforceException.class).hasMessage("WORKFORCE_FORBIDDEN");}
 void denyActiveTemplateStore(){doAnswer(c->{var q=(com.rpb.reservation.appgate.application.AppGateAccessRequest)c.getArgument(0);return q.storeId().equals(store)?com.rpb.reservation.appgate.domain.AppGateDecision.deny(q.appKey(),q.tenantId(),q.storeId(),q.requiredPermission(),com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_EXPIRED):com.rpb.reservation.appgate.domain.AppGateDecision.allow(q.appKey(),q.tenantId(),q.storeId(),q.requiredPermission());}).when(gate).evaluate(any());}
 @Test void activeOldScopeAppGateDenialHidesDraftFromAnotherStore(){draft(false);denyActiveTemplateStore();assertThat(publications.drafts(admin,otherStore)).isEmpty();}
 @Test void activeOldScopeAppGateDenialBlocksNarrowingAndReplay(){var d=draft(false);String before=jdbc.queryForObject("select snapshot::text from workforce_pay_template_masters where id=?",String.class,d.id());denyActiveTemplateStore();for(long expected:List.of(1L,0L))assertThatThrownBy(()->publications.save(admin,otherStore,d.id(),new DraftWrite(expected,"Narrowed",rule("1"),List.of(otherCompany),List.of(otherStore),false))).isInstanceOf(WorkforceException.class).hasMessage("STORE_APP_EXPIRED");assertThat(jdbc.queryForObject("select snapshot::text from workforce_pay_template_masters where id=?",String.class,d.id())).isEqualTo(before);}
}
